for part in T.unroll(2):
    for element in T.vectorized(8):
        q_local[part * 8 + element] = Q[batch_id, token, kv_head * groups + lane % 16, (lane // 16) * 16 + part * 8 + element]
quarter_low = (lane // 16) % 2
quarter_high = lane // 32
for other in T.unroll(2):
    for pair in T.unroll(2):
        send_lo = T.if_then_else(quarter_low == 0, q_local[(other * 2 + 1) * 4 + pair * 2], q_local[(other * 2) * 4 + pair * 2])
        send_hi = T.if_then_else(quarter_low == 0, q_local[(other * 2 + 1) * 4 + pair * 2 + 1], q_local[(other * 2) * 4 + pair * 2 + 1])
        send_word = T.reinterpret('uint16', send_lo).astype('uint32') | (T.reinterpret('uint16', send_hi).astype('uint32') << 16)
        q_receive[other * 2 + pair] = T.shfl_xor(send_word, 16, width=64, mask=0xFFFFFFFFFFFFFFFF)
for cell in T.unroll(4):
    for element in T.vectorized(4):
        received_word = q_receive[(cell // 2) * 2 + element // 2]
        received_value = T.reinterpret('float16', (received_word >> ((element % 2) * 16)).astype('uint16'))
        q_local[cell * 4 + element] = T.if_then_else(cell % 2 == quarter_low, q_local[cell * 4 + element], received_value)
for other in T.unroll(2):
    for pair in T.unroll(2):
        send_lo = T.if_then_else(quarter_high == 0, q_local[(2 + other) * 4 + pair * 2], q_local[(other) * 4 + pair * 2])
        send_hi = T.if_then_else(quarter_high == 0, q_local[(2 + other) * 4 + pair * 2 + 1], q_local[(other) * 4 + pair * 2 + 1])
        send_word = T.reinterpret('uint16', send_lo).astype('uint32') | (T.reinterpret('uint16', send_hi).astype('uint32') << 16)
        q_receive[other * 2 + pair] = T.shfl_xor(send_word, 32, width=64, mask=0xFFFFFFFFFFFFFFFF)
for cell in T.unroll(4):
    for element in T.vectorized(4):
        received_word = q_receive[(cell % 2) * 2 + element // 2]
        received_value = T.reinterpret('float16', (received_word >> ((element % 2) * 16)).astype('uint16'))
        q_local[cell * 4 + element] = T.if_then_else(cell // 2 == quarter_high, q_local[cell * 4 + element], received_value)
